css:
:root {
  --numeric-border: #223151;
  --numeric-background: #D7D8DB;
  --numeric-text: #000000;
  --numeric-unit: #C11C84;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.numeric-widget,
.numeric-widget * {
  box-sizing: border-box;
}

.numeric-widget {
  width: 100%;
  height: 100%;
  padding: 2px;
  overflow: hidden;
  background: transparent;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.numeric-frame {
  width: 100%;
  height: 100%;
  padding: 0;
  overflow: hidden;

  border: 1px solid var(--numeric-border);
  border-radius: 4px;
  background: var(--numeric-background);

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.4),
    inset 0 -1px 0 rgba(85, 93, 105, 0.12);
}

.numeric-screen {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  height: 100%;
  padding: 0 8px;
  overflow: hidden;

  border: none;
  background: transparent;
}

.numeric-reading {
  display: flex;
  flex: 0 0 auto;
  align-items: baseline;
  justify-content: center;
  gap: 0.28em;

  color: var(--numeric-text);

  font-family:
    "IBM Plex Mono",
    Consolas,
    "Liberation Mono",
    monospace;

  font-size: 20px;
  font-weight: 550;
  font-style: normal;
  font-variant-numeric: tabular-nums;
  font-variant-ligatures: none;

  line-height: 1.2;
  letter-spacing: 0;
  white-space: nowrap;
}

.numeric-value,
.numeric-unit {
  display: block;
  flex: 0 0 auto;
}

.numeric-unit {
  font-size: 1em;
  font-weight: inherit;
  color: var(--numeric-unit);
}

