"use strict";

(function () {
  const MAX_FONT_SIZE = 20;

  let screenElement = null;
  let readingElement = null;
  let valueElement = null;
  let lastUpdate = null;
  let resizeObserver = null;

  function fitValue() {
    if (!screenElement || !readingElement) return;

    const styles = getComputedStyle(screenElement);

    const availableWidth =
      screenElement.clientWidth -
      (parseFloat(styles.paddingLeft) || 0) -
      (parseFloat(styles.paddingRight) || 0);

    const availableHeight =
      screenElement.clientHeight -
      (parseFloat(styles.paddingTop) || 0) -
      (parseFloat(styles.paddingBottom) || 0);

    if (availableWidth <= 0 || availableHeight <= 0) return;

    const baseSize = Math.min(
      MAX_FONT_SIZE,
      availableHeight * 0.56
    );

    readingElement.style.fontSize = baseSize + "px";

    const textWidth = readingElement.scrollWidth;
    const targetWidth = Math.max(1, availableWidth - 2);

    if (textWidth > targetWidth) {
      readingElement.style.fontSize =
        (baseSize * targetWidth / textWidth) + "px";
    }
  }

  function render(w) {
    if (!valueElement || !readingElement) return;

    const raw = w ? w.value : null;
    let numericValue = NaN;

    if (typeof raw === "number") {
      numericValue = raw;
    } else if (
      typeof raw === "string" &&
      raw.trim() !== ""
    ) {
      numericValue = Number(raw);
    }

    const valid = Number.isFinite(numericValue);
    const text = valid ? String(numericValue) : "—";

    /*
     * Muestra el valor recibido sin redondearlo ni escalarlo.
     * Por ejemplo: un valor de 70 se muestra como 70 %.
     */
    valueElement.textContent = text;

    readingElement.setAttribute(
      "aria-label",
      valid
        ? "Porcentaje: " + text + " por ciento"
        : "Sin valor numérico"
    );

    fitValue();
  }

  window.onWidgetUpdate = function (w) {
    lastUpdate = w;
    render(w);
  };

  function initialize() {
    screenElement = document.querySelector(".numeric-screen");
    readingElement = document.querySelector(".numeric-reading");
    valueElement = document.querySelector(".numeric-value");

    if (!screenElement || !readingElement || !valueElement) {
      return;
    }

    render(lastUpdate || window.WIDGET || null);

    requestAnimationFrame(fitValue);

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(fitValue);
    }

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(fitValue);
      resizeObserver.observe(screenElement);
    } else {
      window.addEventListener("resize", fitValue);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
